import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Publicacion } from '../../publicaciones/entities/publicacion.entity';
import { Autor } from '../../autores/entities/autor.entity';

@Injectable()
export class AsignarAutorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Publicacion) private readonly publicaciones: Repository<Publicacion>,
    @InjectRepository(Autor) private readonly autores: Repository<Autor>
  ) {}

  buscarPublicacionRepository(publicacionId: number) {
    return this.publicaciones.findOneBy({ id: publicacionId });
  }

  buscarAutorRepository(autorId: number) {
    return this.autores.findOneBy({ id: autorId });
  }

  async asignarAutorRepository(publicacionId: number, autorId: number, rol: string) {
    const asignacion = { publicacionId, autorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarAutorRepository } from './repository';

@Injectable()
export class AsignarAutorService {
  constructor(private readonly repository: AsignarAutorRepository) {}

  async asignarAutorService(publicacionId: number, autorId: number, rol: string) {
    const publicacion = await this.repository.buscarPublicacionRepository(publicacionId);
    const autor = await this.repository.buscarAutorRepository(autorId);
    if (!publicacion || !autor) {
      throw new NotFoundException('No existe la publicacion o el autor');
    }

    try {
      return await this.repository.asignarAutorRepository(publicacionId, autorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El autor ya está asignado a esa publicacion');
      }
      throw error;
    }
  }
}

